using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Web.Script.Serialization;
internal static class PetQuotaVisualTests {
 static int checks;
 static void Need(bool condition,string message){checks++;if(!condition)throw new Exception(message);}
 static void Near(double actual,double expected,double tolerance,string message){Need(Math.Abs(actual-expected)<tolerance,message+": "+actual);}
 [STAThread]static int Main(string[] args){try{
  string root=args[0],outDir=args[1];Directory.CreateDirectory(outDir);
  var spin=new PetRefreshAnimation();Near(spin.At(400).Angle,0,.001,"Idle arrow is not upright");Need(spin.At(400).ArrowOpacity==1&&spin.At(400).CheckOpacity==0,"Idle refresh shows a check");
  spin.Begin(123.456);Near(spin.At(123.456).Angle,0,.001,"Refresh inherits an unrelated animation clock");Near(spin.At(123.681).Angle,90,.001,"Refresh speed changes with the starting timestamp");Need(spin.Waiting,"Refresh is not waiting for its result");
  Near(spin.At(124.355).Angle,359.6,.001,"Full turn lost continuity before wrap");Near(spin.At(124.357).Angle,360.4,.001,"Full turn jumped at wrap");
  spin=new PetRefreshAnimation();spin.Begin(0);spin.Complete(.01,true);Need(!spin.Waiting,"Completion still awaits network");double prev=0;int samples=0;for(double t=0;t<=1.5;t+=.01){var f=spin.At(t);Need(f.Angle>=prev-.00001,"Arrow moved backwards while settling");Need(f.Angle-prev<=4.00001,"Completion jumped to the initial angle");if(f.CheckOpacity>0){Need(f.Angle>=359.999&&!f.Turning,"Success check appeared before completing a full turn");samples++;}prev=f.Angle;}Need(samples>20,"Success check was never displayed");Near(spin.At(1.2).Angle,360,.001,"Fast request did not settle at one whole turn");Need(spin.At(1.3).CheckOpacity==1&&spin.At(1.3).CheckProgress==1,"Success check did not complete its drawing");Need(spin.At(3).ArrowOpacity==1&&spin.At(3).CheckOpacity==0,"Success check does not return to a usable refresh control");
  var fail=new PetRefreshAnimation();fail.Begin(5);fail.Complete(5.2,false);for(double t=5;t<9;t+=.05)Need(fail.At(t).CheckOpacity==0,"Failed quota request falsely displays success");Near(fail.At(9).Angle,360,.001,"Failed quota request snaps away from its whole-turn finish");
  var slow=new PetRefreshAnimation();slow.Begin(10);double before=slow.At(12.25).Angle;slow.Complete(12.25,true);Near(slow.At(12.25).Angle,before,.001,"Long request completion changes the arrow position");Need(slow.At(12.25).Turning&&slow.At(12.25).CheckOpacity==0,"Long request cut its last turn short");Near(slow.At(14).Angle,1080,.001,"Long request did not settle at a whole turn");slow.Begin(14);Need(slow.At(14).Angle==0&&slow.At(14).CheckOpacity==0,"A new refresh inherits the old confirmation");slow.Complete(14.1,false);slow.Complete(14.2,true);Need(slow.At(16).CheckOpacity==0,"Duplicate completion overwrites a failure as success");
  var repeat=new PetRefreshAnimation();repeat.Begin(0);repeat.Complete(.04,true);double phase=repeat.At(.95).Angle;Need(phase>330&&phase<360,"Repeat fixture is not in its deceleration phase");repeat.Begin(.95);Near(repeat.At(.95).Angle,phase,.0001,"A second request jumps the settling arrow back to zero");repeat.Complete(.97,true);double next=repeat.At(.951).Angle;Need(next>=phase&&next-phase<.5,"A second request does not continue clockwise");Need(repeat.At(3).Angle-phase>=359.99,"Second request did not complete its own full turn");
  for(int i=1;i<15;i++){double now=10+i*.15,beforeAngle=repeat.At(now).Angle%360;repeat.Begin(now);double afterAngle=repeat.At(now).Angle%360;Need(Math.Min(Math.Abs(afterAngle-beforeAngle),360-Math.Abs(afterAngle-beforeAngle))<.001,"Repeated refresh introduces an orientation jump");repeat.Complete(now+.02,i%2==0);}
  using(var painter=new PetPainter(root)){
   var prefs=new PetPreferences{CapsuleOpacity=0};painter.ApplyAppearance(prefs);var quota=new PetQuotaSnapshot{CheckedUtc=DateTime.UtcNow,Short=new PetQuotaWindow{Remaining=100,Minutes=300},Week=new PetQuotaWindow{Remaining=72,Minutes=10080}};
   using(var clear=painter.RenderCapsule(2,quota,"","执行/思考",false,0)){
    var bounds=painter.QuotaLabelBounds("100%");Need(bounds.Left>3&&bounds.Right<37&&bounds.Top>3&&bounds.Bottom<37,"Percent glyph is clipped by the dial");
    int light=0,dark=0;for(int y=(int)((bounds.Top+7)*2);y<Math.Ceiling((bounds.Bottom+7)*2);y++)for(int x=(int)((bounds.Left+228)*2);x<Math.Ceiling((bounds.Right+228)*2);x++){var c=clear.GetPixel(x,y);if(c.A>245&&c.R>240&&c.G>240&&c.B>240)light++;if(c.A>240&&c.R<35&&c.G<45&&c.B<65)dark++;}
    Need(light>40,"Transparent percentage has no solid light glyph core");Need(dark>40,"Transparent percentage has no dark outline for pale backgrounds");Need(clear.GetPixel(248*2,16*2).A==0,"Percent contrast repair introduces an opaque circular background");
    using(var board=new Bitmap(600,230))using(var g=Graphics.FromImage(board)){g.Clear(Color.FromArgb(22,27,35));for(int i=0;i<3;i++){var bg=i==0?Color.White:i==1?Color.FromArgb(15,20,28):Color.FromArgb(150,175,191);using(var fill=new SolidBrush(bg))g.FillRectangle(fill,i*200,0,200,230);if(i==2)for(int k=0;k<16;k++)using(var pen=new Pen(k%2==0?Color.FromArgb(30,42,52):Color.FromArgb(238,224,207),9))g.DrawLine(pen,400,k*15,600,k*15+40);g.DrawImage(clear,new Rectangle(i*200+16,26,168,32),new Rectangle(0,0,clear.Width,clear.Height),GraphicsUnit.Pixel);g.DrawImage(clear,new Rectangle(i*200+42,88,120,120),new Rectangle(228*2,7*2,40*2,40*2),GraphicsUnit.Pixel);}board.Save(Path.Combine(outDir,"transparent-quota-contrast.png"),ImageFormat.Png);}
   }
   painter.BeginQuotaRefresh(100);painter.CompleteQuotaRefresh(100.02,true);using(var done=painter.RenderPanel(3,false,quota,"","执行/思考",false,101.3,null,0,false,false,null,0))done.Save(Path.Combine(outDir,"quota-refresh-success.png"),ImageFormat.Png);
  }
  File.WriteAllText(Path.Combine(outDir,"result.json"),new JavaScriptSerializer().Serialize(new{pass=true,checks,fullTurnWithoutSnap=true,requestLocalClock=true,successCheck=true,failureDoesNotCheck=true,transparentPercentDualContrast=true}));return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(args[1],"result.json"),new JavaScriptSerializer().Serialize(new{pass=false,checks,error=e.ToString()}));return 1;}}
}
